import {CATEGORIES,SEED,clone,id,interval,dateLabel,validateDate,fits,recallQuestions,gaps,safeImport,yearStart} from './model.js';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={dots:'M5 12h.01M12 12h.01M19 12h.01',home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',timeline:'M6 3v18M3 6h6M3 18h6M12 6h8M12 12h6M12 18h8',spark:'m12 2 2.7 7.3L22 12l-7.3 2.7L12 22l-2.7-7.3L2 12l7.3-2.7Z',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M17 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.9M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',plus:'M12 5v14M5 12h14',minus:'M5 12h14',close:'m6 6 12 12M18 6 6 18',lock:'M5 10h14v11H5ZM8 10V6a4 4 0 0 1 8 0v4M12 14v3',compass:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M16 8l-3 5-5 3 3-5Z',book:'M12 5v16M12 5C8 2 4 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-4-1-7-2-10 1',case:'M3 7h18v14H3ZM8 7V3h8v4M3 12c6 3 12 3 18 0M12 11v5',sun:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0M12 1v2M12 21v2M1 12h2M21 12h2M4 4l2 2M18 18l2 2M4 20l2-2M18 6l2-2',search:'M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0m-2 6 6 6',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v5l3 2',edit:'m16 3 5 5-12 12-6 1 1-6ZM13 6l5 5',share:'M12 16V3m-4 4 4-4 4 4M5 10v11h14V10',chevron:'m9 6 6 6-6 6',check:'m5 12 4 4L20 5',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',leaf:'M20 3C10 2 3 7 4 14c1 8 14 8 16-11ZM4 21l10-12',mail:'M3 5h18v14H3Zm0 0 9 8 9-8',upload:'M12 17V3m-5 5 5-5 5 5M3 16v5h18v-5',download:'M12 3v14m-5-5 5 5 5-5M3 18v3h18v-3',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 11v6M12 7h.01',image:'M3 3h18v18H3ZM3 17l6-7 5 5 3-3 4 5M17 7h.01',dice:'M5 3h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2M8 8h.01M16 8h.01M8 16h.01M16 16h.01M12 12h.01'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.spark}"/></svg>`;
const btn=(text,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const category=m=>CATEGORIES.find(c=>c.id===(typeof m==='string'?m:m.category))||CATEGORIES.at(-1);
const statusLabel={confirmed:'Je m’en souviens',uncertain:'Souvenir incertain',hypothesis:'Piste à vérifier'};
const badge=m=>`<span class="pill ${m.status}">${m.status==='confirmed'?icon('check'):''}${statusLabel[m.status]||statusLabel.uncertain}</span>`;
const STORE='memoryx-public-v2';
const fresh=()=>({version:2,scope:'demo',demo:{memories:clone(SEED),requests:[],contributions:[]},own:{memories:[],requests:[],contributions:[]},name:'Mon histoire',prefs:{reminders:false,cadence:'weekly',time:'18:30'},visits:0});
let db=fresh(),storageOK=true,storageMessage='';
try {const saved=localStorage.getItem(STORE);if(saved){const parsed=JSON.parse(saved);if(parsed.version!==2||!Array.isArray(parsed.demo?.memories)||!Array.isArray(parsed.own?.memories))throw Error('state');db=parsed;}}catch(e){storageMessage='Les données enregistrées n’ont pas pu être lues. Exporte tes essais avant de fermer cet onglet.';storageOK=false;}
const active=()=>db[db.scope];const memories=()=>active().memories.filter(m=>!m.deleted);const getMemory=mid=>active().memories.find(m=>m.id===mid&&!m.deleted);
function persist(){try{localStorage.setItem(STORE,JSON.stringify(db));storageOK=true;storageMessage='';return true;}catch(e){storageOK=false;storageMessage='Enregistrement impossible sur cet appareil. Tes changements restent dans cet onglet : exporte-les avant de le fermer.';toast(storageMessage);return false;}}
let route=location.hash.slice(1)||'timeline',filter={category:'all',query:''},zoom=8,centerTime=Date.UTC(2022,5,1),timelineScroll=null,editor=null,session=null,sessionSetup={mode:'mixed',category:'all',scope:'all',period:'2019',drawYear:2011,drawCat:'travel'},sourceContext=null,shareContext=null,lastFocus=null;
let timelineMeta=null,scrollRAF=0,toastTimer,zoomAnchorId=null;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function savedToast(message){toast(storageOK?message:'Changement gardé dans cet onglet. Exporte-le pour le conserver.');}
const brand=`<span class="brand"><img src="assets/favicon.svg" alt=""><span>Memory<span class="x">X</span></span></span>`;
function go(r){if(r==='home')r='timeline';if($('#dialog').open)closeDialog();if(route==='timeline')rememberTimeline();route=r;location.hash=r;render();$('#main').focus({preventScroll:true});window.scrollTo(0,0);}
function render(focus=false){if(route==='home'||!['timeline','session','friends','settings'].includes(route))route='timeline';
 $('#shell').innerHTML=`<div class="app modern-app"><header class="topbar"><a href="#timeline" data-route="timeline" class="logo-link">${brand}</a><nav class="desktop-tabs" aria-label="Navigation principale">${[['timeline','Ma frise'],['session','Jouer'],['friends','Ensemble']].map(([r,l])=>`<a href="#${r}" data-route="${r}" class="${route===r?'active':''}" ${route===r?'aria-current="page"':''}>${l}</a>`).join('')}</nav><div class="header-tools"><button class="scope-button" data-action="scope">${db.scope==='demo'?'Exemple':'Mon histoire'}${icon('chevron')}</button><button class="iconbtn share-app" data-action="share-app" aria-label="Partager le lien de MemoryX">${icon('share')}</button><button class="iconbtn" data-action="about" aria-label="À propos et conditions de la démo">${icon('info')}</button><button class="iconbtn account-btn" data-route="settings" aria-label="Mes données et réglages">${icon('dots')}</button></div></header>${!storageOK?`<div class="storage-warning" role="alert">${esc(storageMessage)}</div>`:''}<main class="main ${route==='timeline'?'frise-main':''}" id="main" tabindex="-1">${({timeline:timelineView,session:sessionView,friends:friendsView,settings:settingsView}[route])()}</main><nav class="mobile-dock" aria-label="Navigation mobile"><a href="#timeline" data-route="timeline" class="${route==='timeline'?'active':''}">${icon('timeline')}<span>Ma frise</span></a><button data-action="add" class="dock-add" aria-label="Ajouter un souvenir">${icon('plus')}</button><a href="#session" data-route="session" class="${route==='session'?'active':''}">${icon('spark')}<span>Jouer</span></a></nav></div>`;
 if(route==='timeline')mountTimeline();if(focus)$('#main').focus({preventScroll:true});
}
function footer(){return '';}
function media(m,cls='memory-image'){return m.photo?`<img class="${cls}" src="${m.photo}" alt="${esc(m.title)}">`:m.art?`<img class="${cls}" src="assets/${m.art}.webp" alt="${esc(m.title)}" loading="lazy">`:`<div class="${cls} memory-symbol">${icon(category(m).icon)}</div>`;}
function card(m){return `<button class="memory-card" data-action="detail" data-id="${esc(m.id)}">${media(m)}<div class="body"><span class="eyebrow" style="color:var(--rust)">${esc(dateLabel(m.date))}</span><h3>${esc(m.title)}</h3><p>${esc(m.place||category(m).name)}${m.people?.length?' · '+esc(m.people.slice(0,2).join(', ')):''}</p><div class="cardfoot"><span>${m.status==='confirmed'?'Un moment à revisiter':'Un détail à retrouver'}</span>${icon('arrow')}</div></div></button>`;}
function pagehead(eyebrow,title,sub,action=''){return `<div class="pagehead"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function chips(selected,attr='category'){return `<div class="chips">${CATEGORIES.map(c=>`<button class="chip ${selected===c.id?'selected':''}" data-${attr}="${c.id}" aria-pressed="${selected===c.id}">${icon(c.icon)}${c.name}</button>`).join('')}</div>`;}
function timelineView(){const ms=memories(),matched=ms.filter(m=>fits(m,filter)),dated=matched.filter(m=>interval(m.date)),undated=matched.filter(m=>!interval(m.date));const years=[...new Set(dated.map(m=>new Date(interval(m.date)[0]).getUTCFullYear()))].sort((a,b)=>b-a);return `<div class="frise-heading"><h1>Ma frise<span class="title-dot">.</span></h1><div class="frise-actions"><button class="iconbtn" data-action="toggle-search" aria-label="Rechercher un souvenir">${icon('search')}</button>${undated.length?`<button class="undated-btn" data-action="undated">Sans date <span>${undated.length}</span></button>`:''}${btn(icon('plus')+' Ajouter','add','desktop-add')}</div></div><div class="frise-filters">${chips(filter.category)}<div class="searchbox ${filter.query?'':'collapsed'}" id="timeline-search">${icon('search')}<input class="input" id="memory-search" aria-label="Chercher dans mes souvenirs" placeholder="Un lieu, un prénom…" value="${esc(filter.query)}"></div></div>${dated.length?`<div class="timeline-stage"><nav class="year-rail" aria-label="Parcourir les années">${years.map(y=>`<button data-action="jump-year" data-year="${y}">${y}</button>`).join('')}<button class="rail-all" data-action="zoom-fit">Tout voir</button></nav><div class="timeline-viewport" id="timeline-viewport" tabindex="0" role="region" aria-label="Frise de vie, défilement vertical"><div id="timeline-canvas" class="timeline-canvas"></div></div><div class="zoom-float"><button class="iconbtn" aria-label="Dézoomer la frise" data-action="zoom-out">${icon('minus')}</button><input type="range" min="0" max="100" value="${zoom}" id="zoom" aria-label="Niveau de zoom de la frise"><button class="iconbtn" aria-label="Zoomer la frise" data-action="zoom-in">${icon('plus')}</button></div></div>`:undated.length?`<div class="undated-list">${undated.map(card).join('')}</div>`:`<div class="frise-empty"><span class="empty-orbit">${icon('spark')}</span><h2>${ms.length?'Aucun souvenir ici.':'Quel souvenir te revient ?'}</h2>${ms.length?btn('Tout afficher','clear-filter','light'):btn('Ajouter mon premier souvenir '+icon('plus'),'add')}<button class="textbtn" data-action="${ms.length?'clear-filter':'demo'}">${ms.length?'Changer de recherche':'Explorer un exemple'}</button></div>`}`;}

const YEAR=365.2425*86400000;
function rememberTimeline(){const v=$('#timeline-viewport');if(v&&timelineMeta){timelineScroll=v.scrollTop;centerTime=timelineMeta.end-(v.scrollTop+v.clientHeight/2-45)/timelineMeta.scale*YEAR;}}
function timelineLayout(){const all=memories().map(m=>interval(m.date)).filter(Boolean);const start=yearStart(Math.min(...all.map(i=>new Date(i[0]).getUTCFullYear()),new Date().getFullYear())-1),end=yearStart(Math.max(...all.map(i=>new Date(i[1]).getUTCFullYear()),new Date().getFullYear())+1),scale=34*Math.exp(zoom/13);let last=-200,lastHeight=0;const mobile=window.innerWidth<=640;const entries=memories().filter(m=>fits(m,filter)&&interval(m.date)).map(m=>{const i=interval(m.date),anchor=['exact','range'].includes(m.date.type)?i[0]:(i[0]+i[1])/2;return {m,i,anchor};}).sort((a,b)=>b.anchor-a.anchor).map(e=>{const actual=45+(end-e.anchor)/YEAR*scale,height=e.m.art||e.m.photo?(mobile?190:240):(mobile?145:175),y=Math.max(actual,last+lastHeight+40);last=y;lastHeight=height;return {...e,y,actual,height};});return {start,end,scale,entries,height:Math.max((end-start)/YEAR*scale+180,last+lastHeight+100,500)};}
function mountTimeline(){const v=$('#timeline-viewport');if(!v)return;timelineMeta=timelineLayout();$('#timeline-canvas').style.height=timelineMeta.height+'px';const target=timelineMeta.entries.reduce((a,b)=>!a||Math.abs(b.anchor-centerTime)<Math.abs(a.anchor-centerTime)?b:a,null);v.scrollTop=timelineScroll!==null?timelineScroll:Math.max(0,(target?.y||0)-30);paintTimeline();v.addEventListener('wheel',()=>zoomAnchorId=null,{passive:true});v.addEventListener('touchstart',()=>zoomAnchorId=null,{passive:true});v.addEventListener('keydown',()=>zoomAnchorId=null);v.addEventListener('scroll',()=>{cancelAnimationFrame(scrollRAF);scrollRAF=requestAnimationFrame(paintTimeline);});}
function paintTimeline(){const v=$('#timeline-viewport');if(!v)return;const {end,scale,entries}=timelineMeta,top=v.scrollTop,bottom=top+v.clientHeight,minT=end-(bottom+150-45)/scale*YEAR,maxT=end-(top-150-45)/scale*YEAR;let tick=new Date(minT),step,unit;if(scale<100){unit='year';step=5;}else if(scale<180){unit='year';step=2;}else if(scale<600){unit='year';step=1;}else if(scale<1800){unit='month';step=3;}else if(scale<15000){unit='month';step=1;}else{unit='day';step=scale>50000?1:7;}
 if(unit==='year')tick=new Date(Date.UTC(Math.floor(tick.getUTCFullYear()/step)*step,0,1));else if(unit==='month')tick=new Date(Date.UTC(tick.getUTCFullYear(),Math.floor(tick.getUTCMonth()/step)*step,1));else tick=new Date(Date.UTC(tick.getUTCFullYear(),tick.getUTCMonth(),1));let ticks='',n=0;while(+tick<maxT&&n++<100){const y=45+(end-+tick)/YEAR*scale;if(y>top-150&&y<bottom+150){const l=unit==='year'?tick.getUTCFullYear():new Intl.DateTimeFormat('fr-FR',unit==='month'?{month:'short',year:'2-digit',timeZone:'UTC'}:{day:'numeric',month:'short',timeZone:'UTC'}).format(tick);ticks+=`<div class="tick ${unit}" style="top:${y}px"><span>${l}</span></div>`;}if(unit==='year')tick.setUTCFullYear(tick.getUTCFullYear()+step);else if(unit==='month')tick.setUTCMonth(tick.getUTCMonth()+step);else tick.setUTCDate(tick.getUTCDate()+step);}
 const visible=entries.filter(e=>e.y+e.height>top-300&&e.y<bottom+300),mobile=window.innerWidth<=640,axis=mobile?15:84;let bars='';for(const e of entries){if(e.m.date.type==='exact')continue;const y1=45+(end-e.i[1])/YEAR*scale,y2=45+(end-e.i[0])/YEAR*scale;if(y2>=top&&y1<=bottom)bars+=`<div class="rangebar" style="top:${Math.max(y1,top)}px;height:${Math.min(y2,bottom)-Math.max(y1,top)}px" title="${esc(dateLabel(e.m.date))}"></div>`;}
 const cards=visible.map(e=>`<div class="time-dot" style="top:${e.y+22}px"></div><button class="time-event ${e.m.art||e.m.photo?'has-image':'text-memory'}" data-action="detail" data-id="${e.m.id}" style="top:${e.y}px;height:${e.height}px" aria-label="${esc(e.m.title+', '+dateLabel(e.m.date))}"><div class="event-copy"><span class="event-date">${esc(dateLabel(e.m.date))}</span><h3>${esc(e.m.title)}</h3><p class="event-excerpt">${esc(e.m.text?.split('. ')[0]?.slice(0,85)||'')}</p><span class="event-meta">${e.m.place?icon('pin')+esc(e.m.place):esc(category(e.m).name)}${e.m.status!=='confirmed'?'<span class="uncertainty-dot" title="Souvenir à préciser"></span>':''}</span></div><div class="event-visual">${media(e.m,'event-image')}<span class="open-memory">${icon('arrow')}</span></div></button>`).join('');
 let connectors=visible.map(e=>`<svg class="time-connector" style="left:${axis}px;top:${Math.min(e.actual,e.y+22)}px" width="28" height="${Math.max(30,e.y+22-e.actual+5)}" aria-hidden="true"><path d="M0 3Q8 15 0 ${e.y+22-e.actual}" fill="none" stroke="#c3bdf8" stroke-width="1"/><circle cx="0" cy="3" r="2.5" fill="#a89ef4"/></svg>`).join('');
 $('#timeline-canvas').innerHTML=`<div class="axis"></div>${ticks}${bars}${connectors}${cards}${!visible.length?`<button class="timeline-nearest" data-action="nearest">${icon('compass')}Revenir à un souvenir</button>`:''}`;
 const nearest=entries.reduce((a,b)=>!a||Math.abs(b.y-top)<Math.abs(a.y-top)?b:a,null);document.querySelectorAll('.year-rail [data-year]').forEach(b=>{const y=nearest&&new Date(nearest.i[0]).getUTCFullYear();b.classList.toggle('current',+b.dataset.year===y);});
}
function changeZoom(z){const v=$('#timeline-viewport');if(!v)return;const selected=zoomAnchorId&&getMemory(zoomAnchorId),si=selected&&interval(selected.date),anchor=si?(['exact','range'].includes(selected.date.type)?si[0]:(si[0]+si[1])/2):timelineMeta.end-(v.scrollTop+v.clientHeight/2-45)/timelineMeta.scale*YEAR;zoom=Math.max(0,Math.min(100,z));$('#zoom').value=zoom;timelineMeta=timelineLayout();$('#timeline-canvas').style.height=timelineMeta.height+'px';const e=selected&&timelineMeta.entries.find(e=>e.m.id===selected.id);v.scrollTop=Math.max(0,(e?.y??45+(timelineMeta.end-anchor)/YEAR*timelineMeta.scale)-v.clientHeight/2);paintTimeline();}

function showDialog(title,body){const d=$('#dialog');if(!d.open)lastFocus=document.activeElement;d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title" tabindex="-1">${title}</h2><button class="iconbtn" data-action="close" aria-label="Fermer">${icon('close')}</button></div>${body}`;if(!d.open)d.showModal();else $('#dialog-title').focus({preventScroll:true});d.scrollTop=0;}
function closeDialog(){if(editor)captureEditor();$('#dialog').close();(lastFocus?.isConnected&&lastFocus!==document.body?lastFocus:$('#main'))?.focus?.({preventScroll:true});}
function detail(mid){const m=getMemory(mid);if(!m){toast('Ce souvenir n’est plus disponible.');return;}editor=null;const cs=active().contributions.filter(c=>c.memoryId===mid&&c.state==='accepted');showDialog('Souvenir',`${m.art||m.photo?media(m,'detail-hero'):''}<div class="detail-head">${badge(m)}<h2>${esc(m.title)}</h2><div class="detail-facts"><span class="row">${icon('clock')}${esc(dateLabel(m.date))}</span>${m.place?`<span class="row">${icon('pin')}${esc(m.place)}</span>`:''}${m.people?.length?`<span class="row">${icon('people')}${esc(m.people.join(', '))}</span>`:''}</div></div><div class="detail-text">${esc(m.text||'')}</div><details class="detail-source"><summary>Origine</summary><p>${esc(m.source||'Ma note personnelle')}</p></details>${(m.clues||[]).length?`<h3>Des pistes à vérifier</h3>${m.clues.map(c=>`<div class="contribution"><span class="pill hypothesis">Hypothèse</span><p>${esc(c.text)}</p><small>${esc(c.source)}</small><div class="review-buttons">${btn('Retirer cette piste','remove-clue','light sm',`data-id="${mid}" data-clue="${c.id}"`)}</div></div>`).join('')}`:''}${cs.length?`<h3>Les souvenirs de tes proches</h3>${cs.map(c=>`<div class="contribution"><span class="small">${esc(c.person)} · Témoignage conservé, à vérifier</span><p>${esc(c.text)}</p><small>${c.certainty==='sure'?'Souvenir de cette personne':'À préciser'}</small></div>`).join('')}`:''}<div class="detail-controls"><div class="row wrap">${btn(icon('edit')+' Modifier','edit','light sm',`data-id="${mid}"`)}${interval(m.date)?btn(icon('timeline')+' Situer','focus-memory','light sm',`data-id="${mid}"`):''}${btn(icon('share')+' Partager','share','sm',`data-id="${mid}"`)}</div><button class="textbtn danger" data-action="delete-memory" data-id="${mid}">${icon('trash')}Retirer</button></div><div class="guidance"><h3>Un détail te manque ?</h3><div class="row wrap">${btn('Me rappeler','recall-help','light sm',`data-id="${mid}"`)}${btn('Chercher des indices','source','light sm',`data-id="${mid}"`)}${btn('Demander à un proche','ask','light sm',`data-id="${mid}"`)}</div></div>`);}
function dateFields(d){if(d.type==='unknown')return '';if(d.type==='month')return `<div class="field"><label for="date-month">Quel mois ?</label><input id="date-month" name="month" type="month" value="${esc(d.month||'')}"></div>`;if(d.type==='exact')return `<div class="field"><label for="date-exact">Quel jour ?</label><input id="date-exact" name="exact" type="date" min="1000-01-01" max="2100-12-31" value="${esc(d.exact||'')}"></div>`;if(d.type==='range')return `<div class="twocol"><div class="field"><label for="date-start">De l’année</label><input id="date-start" name="start" type="number" min="1000" max="2100" value="${esc(d.start||'')}" placeholder="2010"></div><div class="field"><label for="date-end">À l’année, incluse</label><input id="date-end" name="end" type="number" min="1000" max="2100" value="${esc(d.end||'')}" placeholder="2013"></div></div>`;return `<div class="twocol"><div class="field"><label for="date-year">${d.type==='approx'?'Autour de quelle année ?':'Quelle année ?'}</label><input id="date-year" name="year" type="number" min="1000" max="2100" value="${esc(d.year||'')}" placeholder="2019"></div>${d.type==='season'?`<div class="field"><label for="date-season">La saison</label><select id="date-season" name="season">${[['spring','Printemps'],['summer','Été'],['autumn','Automne'],['winter','Hiver (décembre à février)']].map(([v,l])=>`<option value="${v}" ${d.season===v?'selected':''}>${l}</option>`).join('')}</select></div>`:''}</div>${d.type==='approx'?'':''}`;}
function editMemory(mid=null,preset={}){const existing=mid?getMemory(mid):null;editor={...clone(existing||{id:id(),title:'',text:'',date:{type:'unknown'},category:'daily',place:'',people:[],status:'uncertain',source:'Ma note personnelle',example:db.scope==='demo'}),...preset,editing:!!existing};renderEditor();}
function captureEditor(){const f=$('#memory-form');if(!editor||!f)return;const data=new FormData(f);editor._dateOpen=$('#editor-date')?.open;editor._detailsOpen=$('#editor-details')?.open;editor.title=data.get('title')||'';editor.text=data.get('text')||'';editor.place=data.get('place')||'';editor.people=(data.get('people')||'').split(',').map(x=>x.trim()).filter(Boolean);editor.status=data.get('status')||'uncertain';const d={type:editor.date.type};for(const k of ['year','start','end','exact','season','month'])if(data.has(k))d[k]=['year','start','end'].includes(k)?data.get(k)===''?'':+data.get(k):data.get(k);editor.date=d;}
function renderEditor(){showDialog(editor.editing?'Modifier ce souvenir':'Ajouter un souvenir',`<form id="memory-form" novalidate><div class="field"><label class="sr-only" for="memory-title">Quel souvenir te revient ?</label><input class="editor-title" id="memory-title" name="title" maxlength="100" value="${esc(editor.title)}" placeholder="Un titre, quelques mots…" required autofocus></div><div class="field"><label class="sr-only" for="memory-text">Ce dont tu te souviens</label><textarea class="editor-text" id="memory-text" name="text" maxlength="6000" placeholder="Ce qui me revient…">${esc(editor.text)}</textarea></div><details class="editor-extra" id="editor-date" ${editor._dateOpen||editor.date.type!=='unknown'?'open':''}><summary>${icon('clock')}${editor.date.type==='unknown'?'Ajouter une date':esc(dateLabel(editor.date))}</summary><div class="button-group" style="margin-bottom:18px">${[['exact','Jour'],['month','Mois'],['season','Saison'],['year','Année'],['approx','Vers…'],['range','Période'],['unknown','Sans date']].map(([v,l])=>`<button type="button" class="chip ${editor.date.type===v?'selected':''}" aria-pressed="${editor.date.type===v}" data-date-type="${v}">${l}</button>`).join('')}</div><div id="date-fields">${dateFields(editor.date)}</div></details><details class="editor-extra" id="editor-details" ${editor._detailsOpen?'open':''}><summary>${icon('plus')}Lieu, personnes et photo</summary><div class="twocol"><div class="field"><label for="memory-place">Où ?</label><input id="memory-place" name="place" maxlength="200" value="${esc(editor.place)}" placeholder="Un lieu"></div><div class="field"><label for="memory-people">Avec qui ?</label><input id="memory-people" name="people" maxlength="500" value="${esc(editor.people.join(', '))}" placeholder="Léa, Max…"></div></div><div class="chips" style="margin-bottom:20px">${CATEGORIES.filter(c=>c.id!=='all').map(c=>`<button type="button" class="chip ${editor.category===c.id?'selected':''}" data-edit-category="${c.id}" aria-pressed="${editor.category===c.id}">${icon(c.icon)}${c.name}</button>`).join('')}</div><div class="field"><label for="memory-photo">Photo</label><input type="file" id="memory-photo" accept="image/png,image/jpeg,image/webp"><small>JPEG, PNG ou WebP · 1,5 Mo maximum.</small></div>${editor.photo?`<img class="photo-preview" src="${editor.photo}" alt="Photo choisie">${btn('Retirer la photo','remove-photo','light sm','type="button"')}`:''}<div id="photo-error" role="status" class="field-error"></div></details><div class="field-error" id="form-error" role="alert"></div><div class="editor-footer"><select class="editor-status" id="memory-status" name="status" aria-label="À quel point ce souvenir est-il clair ?">${Object.entries(statusLabel).map(([v,l])=>`<option value="${v}" ${editor.status===v?'selected':''}>${l}</option>`).join('')}</select><button class="btn" type="submit">${editor.editing?'Enregistrer':'Garder ce souvenir'} ${icon('check')}</button></div></form>`);}

function saveMemory(e){e.preventDefault();captureEditor();if(!editor.title.trim()){$('#form-error').textContent='Donne un titre à ce souvenir, même quelques mots.';$('#memory-title').focus();return;}const error=validateDate(editor.date);if(error){$('#form-error').textContent=error;$('#date-fields input')?.focus();return;}const m={...editor,title:editor.title.trim(),updatedAt:new Date().toISOString()};delete m.editing;delete m._dateOpen;delete m._detailsOpen;const arr=active().memories,idx=arr.findIndex(x=>x.id===m.id);if(idx<0)arr.push(m);else arr[idx]=m;persist();editor=null;$('#dialog').close();if(session?.awaitingMemory){session.added.push(m.id);session.awaitingMemory=false;session.saved=m.id;render(true);savedToast('Un souvenir de plus dans ton histoire.');}else if(session&&route==='session'){const st=session.steps[session.index];if(st?.q?.memoryId===m.id){st.q.title=m.title;st.q.when=dateLabel(m.date);st.q.answer=st.q.field==='place'?m.place:m.people.join(', ');}render(true);savedToast('Souvenir corrigé. Tu peux poursuivre ta pause.');}else{route='timeline';location.hash=route;const i=interval(m.date);if(i){centerTime=(i[0]+i[1])/2;timelineScroll=null;}filter={category:'all',query:''};render();detail(m.id);savedToast(idx<0?'Souvenir ajouté à ta frise.':'Souvenir mis à jour.');}}
function die(n,green=false){const cells={1:[4],2:[0,8],3:[0,4,8],4:[0,2,6,8],5:[0,2,4,6,8],6:[0,2,3,5,6,8]}[n];return `<div class="die ${green?'green':''}" aria-hidden="true">${Array.from({length:9},(_,i)=>`<span class="${cells.includes(i)?'pip':''}"></span>`).join('')}</div>`;}
function scopeFilter(){const f={category:sessionSetup.category};const p=sessionSetup.period;if(sessionSetup.scope==='year'&&/^\d{4}$/.test(p)){f.from=yearStart(+p);f.to=yearStart(+p+1);}else if(sessionSetup.scope==='month'&&/^\d{4}-\d{2}$/.test(p)){const [y,m]=p.split('-').map(Number);f.from=Date.UTC(y,m-1,1);f.to=Date.UTC(y,m,1);}else if(sessionSetup.scope==='day'&&/^\d{4}-\d{2}-\d{2}$/.test(p)){f.from=Date.parse(p+'T00:00:00Z');f.to=f.from+86400000;}return f;}
function sessionView(){if(session)return activeSession();const p=sessionSetup;return `<div class="session-wrap"><div class="session-intro"><span class="eyebrow" style="color:var(--rust)"></span><h1 style="margin-top:13px">À quoi on joue ?</h1><p></p></div><div class="session-panel"><span class="small-label"></span><div class="choice-modes">${[['mixed','spark','Les deux',''],['recall','book','Tester ma mémoire',''],['explore','leaf','Compléter mon histoire','']].map(([v,i,l,d])=>`<button class="mode ${p.mode===v?'selected':''}" data-mode="${v}" aria-pressed="${p.mode===v}">${icon(i)}<strong>${l}</strong><small>${d}</small></button>`).join('')}</div><div class="field"><span>Quel fil suivre ?</span>${chips(p.category,'session-category')}</div><div class="twocol"><div class="field"><label for="session-scope">J’explore…</label><select id="session-scope"><option value="all" ${p.scope==='all'?'selected':''}>Toute mon histoire</option><option value="year" ${p.scope==='year'?'selected':''}>Une année</option><option value="month" ${p.scope==='month'?'selected':''}>Un mois</option><option value="day" ${p.scope==='day'?'selected':''}>Un jour</option></select></div>${p.scope!=='all'?`<div class="field"><label for="session-period">${{year:'L’année',month:'Le mois',day:'Le jour'}[p.scope]}</label><input id="session-period" type="${{year:'number',month:'month',day:'date'}[p.scope]}" ${p.scope==='year'?'min="1000" max="2100"':''} value="${esc(p.period)}"></div>`:''}</div><div class="dice-area"><div class="dice-pair"><div>${die(p.die1||3)}<div class="die-label">La période</div></div><div>${die(p.die2||5,true)}<div class="die-label">Le thème</div></div></div><div class="dice-text"><b>${p.drawn?esc(p.drawYear+' · '+category(p.drawCat).name):'Surprise ?'}</b><small>${p.drawn?'':''}</small></div>${btn(icon('dice')+' Lancer les dés','roll','light sm')}</div><div id="session-error" class="field-error" role="alert"></div><div class="btnrow">${btn('Commencer ma pause '+icon('arrow'),'start-session')}</div><p class="small muted" style="margin-top:14px"></p></div></div>${footer()}`;}
function startSession(){if($('#session-period'))sessionSetup.period=$('#session-period').value;const f=scopeFilter();if(sessionSetup.scope!=='all'&&!f.from){$('#session-error').textContent='Choisis une période valide, ou explore toute ton histoire.';return;}if(sessionSetup.scope==='year'&&(+sessionSetup.period<1000||+sessionSetup.period>2100)){ $('#session-error').textContent='Choisis une année entre 1000 et 2100.';return;}
 const qs=recallQuestions(memories(),f),steps=[];let gapYear=f.from?new Date(f.from).getUTCFullYear():gaps(memories())[0]?.year||new Date().getFullYear()-1;const explore={type:'explore',year:gapYear,category:sessionSetup.category==='all'?'daily':sessionSetup.category,period:sessionSetup.scope==='all'?String(gapYear):sessionSetup.period,scope:sessionSetup.scope==='all'?'year':sessionSetup.scope};
 if(sessionSetup.mode!=='explore'&&qs.length)steps.push({type:'recall',q:qs[0]});
 if(sessionSetup.mode!=='recall'||!qs.length)steps.push(explore);
 if(sessionSetup.mode==='mixed'&&qs.length>1){const second=qs.find(q=>q.memoryId!==qs[0].memoryId)||qs[1];steps.push({type:'recall',q:{...second,kind:'card'}});}else if(sessionSetup.mode==='recall'&&qs.length>1)steps.push({type:'recall',q:qs[1]});
 session={steps,index:0,added:[],recalls:0,skipped:0,answer:'',revealed:false,hints:0,branch:null,saved:null,awaitingMemory:false,notice:sessionSetup.mode!=='explore'&&!qs.length?'Aucun détail confirmé à tester dans cette sélection. Commençons par retrouver un souvenir.':''};go('session');}
function sessionPeriod(step){if(step.scope==='day')return dateLabel({type:'exact',exact:step.period});if(step.scope==='month')return new Intl.DateTimeFormat('fr-FR',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(step.period+'-01T12:00:00Z'));return String(step.year);}
function exploreQuestion(step){const period=sessionPeriod(step);return ({places:`Où vivais-tu en ${period} ?`,work:`À quoi ressemblaient tes journées de travail en ${period} ?`,people:`Quel moment avec un proche te revient en ${period} ?`,travel:`Quelle escapade te revient en ${period} ?`,study:`Qu’apprenais-tu en ${period} ?`,daily:`Qu’est-ce qui te revient de ${period} ?`})[step.category];}
function activeSession(){if(session.index>=session.steps.length)return `<div class="session-wrap session-end"><div class="big-star" aria-hidden="true">${icon('spark')}</div><span class="eyebrow">À ton rythme</span><h1 style="margin-top:14px">Ton histoire,<br>un peu plus près.</h1><p>${session.recalls?`${session.recalls} détail${session.recalls>1?'s':''} revisité${session.recalls>1?'s':''}. `:''}${session.added.length?`${session.added.length} souvenir${session.added.length>1?'s':''} ou piste${session.added.length>1?'s':''} ajouté${session.added.length>1?'s':''} à ta frise.`:'Parfois, les souvenirs reviennent un peu plus tard.'}</p><p class="small muted"></p><div class="btnrow">${btn('Retrouver ma frise '+icon('arrow'),'finish-session')}${btn('Une autre pause','restart-session','light')}</div></div>${footer()}`;
 const step=session.steps[session.index];return `<div class="session-wrap"><div class="question-head"><button class="iconbtn" data-action="exit-session" aria-label="Quitter la pause">${icon('close')}</button><div class="progressline" aria-label="Étape ${session.index+1} sur ${session.steps.length}">${session.steps.map((_,i)=>`<span class="${i<=session.index?'done':''}"></span>`).join('')}</div><button class="textbtn" data-action="session-settings">${icon('dice')}Choisir</button></div>${session.notice?`<div class="notice" style="margin-bottom:20px">${esc(session.notice)}</div>`:''}<section class="question">${step.type==='recall'?recallView(step):exploreView(step)}</section></div>${footer()}`;}
function recallView(step){const q=step.q,m=getMemory(q.memoryId);return `<span class="eyebrow">Se rappeler</span><h1>${esc(q.question)}</h1><div class="context-memory">${m?.art?`<img src="assets/${m.art}.webp" alt="Illustration du souvenir">`:icon('book')}<div><b>${esc(q.title)}</b><p>${esc(q.when)}</p></div></div>${!session.revealed?`${q.kind==='free'?`<div class="field"><label for="recall-answer">Ce qui te revient</label><input id="recall-answer" maxlength="300" placeholder="Prends un instant…" value="${esc(session.answer)}" autocomplete="off"></div>`:`<p>Pense à ce moment. Essaie de retrouver les personnes avant de retourner la carte.</p>`}${session.hints?`<div class="inline-hint">${esc(q.hint)}</div>`:''}<div class="btnrow">${btn(q.kind==='card'?'Retourner la carte':'Voir ce que j’avais noté','reveal')}${btn('Un petit indice','hint','light')}</div><button class="textbtn" data-action="reveal" style="margin-top:13px">Je ne sais plus</button>`:`${session.answer?`<p class="small">Tu as pensé à : ${esc(session.answer)}</p>`:''}<div class="reveal"><span class="eyebrow">Dans ton souvenir</span><h2>${esc(q.answer)}</h2><p>Source : « ${esc(q.title)} », ${esc(q.when)}. </p></div><p class="small muted"></p><div class="btnrow">${btn('Continuer '+icon('arrow'),'next-step')}${btn('Je veux corriger ce souvenir','edit','light',`data-id="${q.memoryId}"`)}</div>`}`;}
function exploreView(step){if(session.preparedRequest&&!session.saved)return `<span class="eyebrow">Une question pour retrouver ensemble</span><h1>Une piste à poursuivre.</h1><p>Ta question est conservée dans Ensemble.</p><div class="btnrow">${btn('Continuer ma pause '+icon('arrow'),'next-step')}${btn('Revoir la question','guest','light',`data-id="${session.preparedRequest}"`)}</div>`;if(session.saved){const m=getMemory(session.saved);return `<span class="eyebrow">Une place dans ton histoire</span><h1>${m?.status==='hypothesis'?'Une piste à suivre.':'Un souvenir de plus.'}</h1><div class="reveal">${m?badge(m):''}<h2>${esc(m?.title||'Ta piste a été conservée')}</h2><p>${m?esc(dateLabel(m.date)):''}</p></div><p></p><div class="btnrow">${btn('Continuer ma pause '+icon('arrow'),'next-step')}${m?btn('Revoir ce souvenir','detail','light',`data-id="${m.id}"`):''}</div>`;}
 const hints=['Ferme les yeux un instant : quel lieu ou quelle ambiance revient ?','Avec qui passais-tu du temps ? Une voix, un visage ?','Un trajet, une chanson, une odeur ou un repas peuvent ouvrir une piste.'];return `<span class="eyebrow">Retrouver · ${esc(category(step.category).name)}</span><h1>${esc(exploreQuestion(step))}</h1><p></p>${session.branch==='remember'?`<div class="hint-list">${hints.slice(0,Math.max(1,session.hints)).map(h=>`<p>${h}</p>`).join('')}</div>${session.hints<3?`<button class="textbtn" data-action="more-hint">Une autre piste pour me rappeler ${icon('plus')}</button>`:''}<div class="field" style="margin-top:20px"><label for="explore-note">Ce qui me revient…</label><textarea id="explore-note" maxlength="6000" placeholder="Je me souviens de…">${esc(session.answer)}</textarea></div><div class="btnrow">${btn('En faire un souvenir '+icon('arrow'),'save-explore')}${btn('Essayer une autre voie','choose-path','light')}</div>`:`<div class="pathways"><button class="pathway" data-action="remember"><span class="path-icon">${icon('leaf')}</span><span class="grow"><strong>Me rappeler</strong><small></small></span>${icon('chevron')}</button><button class="pathway" data-action="source"><span class="path-icon">${icon('spark')}</span><span class="grow"><strong>Chercher des indices</strong><small></small></span>${icon('chevron')}</button><button class="pathway" data-action="ask"><span class="path-icon">${icon('people')}</span><span class="grow"><strong>Demander à un proche</strong><small></small></span>${icon('chevron')}</button></div>`}<button class="textbtn" data-action="skip-step" style="margin-top:18px">Pas maintenant, passer ce moment ${icon('arrow')}</button>`;}
function nextStep(skip=false){if(skip)session.skipped++;else if(session.steps[session.index]?.type==='recall')session.recalls++;session.index++;session.answer='';session.revealed=false;session.hints=0;session.branch=null;session.saved=null;session.preparedRequest=null;session.notice='';session.awaitingMemory=false;render(true);window.scrollTo(0,0);}
function explorePreset(){const s=session?.steps[session.index];if(s?.type!=='explore')return {};return {date:s.scope==='day'?{type:'exact',exact:s.period}:s.scope==='month'?{type:'month',month:s.period}:{type:'year',year:s.year},category:s.category};}
function sourceView(mid=null){const step=session?.steps[session.index];sourceContext={memoryId:mid,step:step?.type==='explore'?clone(step):null};editor=null;showSources();}
function demoSources(){return [{id:'ticket',title:'Un billet retrouvé',text:'Traversée au départ de Concarneau. Été 2019.',source:'Billet d’exemple · été 2019',note:'Un billet donne une destination, mais ne prouve pas que le voyage a eu lieu.',memoryText:'Le départ en bateau était peut-être à Concarneau.',date:{type:'season',year:2019,season:'summer'}},{id:'note',title:'Une note de calendrier',text:'Week-end à la mer avec Léa.',source:'Calendrier d’exemple · août 2019',note:'Un événement prévu n’est pas une présence confirmée.',memoryText:'Un week-end à la mer avec Léa était prévu en août 2019.',date:{type:'season',year:2019,season:'summer'}}];}
function showSources(){showDialog('Chercher des indices',`<div class="pathways"><button class="pathway" data-action="demo-sources"><span class="path-icon">${icon('spark')}</span><span class="grow"><strong>Voir des indices d’exemple</strong></span>${icon('chevron')}</button><button class="pathway" data-action="manual-source"><span class="path-icon">${icon('book')}</span><span class="grow"><strong>Ajouter un indice</strong></span>${icon('chevron')}</button></div>`);}
function displayDemoSources(){showDialog('Deux traces, une piste possible',`<p class="small muted">Bretagne, été 2019 · indices d’exemple</p>${demoSources().map(c=>`<article class="source-card"><span class="eyebrow">${esc(c.title)}</span><p>« ${esc(c.text)} »</p><small>${esc(c.source)}</small><div class="notice" style="margin:14px 0">${esc(c.note)}</div>${btn('Garder comme piste','keep-demo-source','light sm',`data-clue="${c.id}"`)}</article>`).join('')}<button class="textbtn" data-action="close">Ne rien conserver</button>`);}
function keepSource(c,example=false){if(example&&db.scope!=='demo'){showDialog('Garder l’exemple à part',`<p>Les indices fictifs restent dans l’histoire d’exemple d’Alex. Ils ne seront pas ajoutés à ton histoire.</p><div class="btnrow">${btn('Explorer l’exemple','demo')}${btn('Revenir à mes indices','source-back','light')}</div>`);return;}
 const target=example?getMemory('coast'):sourceContext.memoryId?getMemory(sourceContext.memoryId):null;
 if(target){target.clues=target.clues||[];if(!target.clues.some(x=>x.text===c.memoryText&&x.source===c.source))target.clues.push({id:id(),text:c.memoryText,source:c.source,status:'hypothesis'});persist();if(session&&session.steps[session.index]?.type==='explore'){session.saved=target.id;session.added.push(target.id);render();}detail(target.id);savedToast('Piste conservée avec sa source, sans modifier le souvenir.');}
 else {if(session)session.awaitingMemory=true;editMemory(null,{...explorePreset(),title:c.title||'Un souvenir à vérifier',text:c.memoryText,date:c.date||explorePreset().date||{type:'unknown'},source:c.source,status:'hypothesis'});}}
function manualSource(){showDialog('Conserver une trace',`<form id="source-form"><div class="field"><label for="source-name">D’où vient cet indice ?</label><input id="source-name" name="source" required maxlength="300" placeholder="Billet de train, note du 12 juillet…"></div><div class="field"><label for="source-text">L’extrait ou le détail qui te semble utile</label><textarea id="source-text" name="text" required maxlength="6000" placeholder="Ce que la trace dit réellement, sans compléter ce qu’elle ne dit pas."></textarea></div><div class="btnrow"><button class="btn" type="submit">Conserver cette piste ${icon('plus')}</button></div></form>`);}
function helpMemory(mid){const m=getMemory(mid);if(!m)return;showDialog('Laisser revenir les détails',`<p class="eyebrow">${esc(m.title)}</p><h2 style="margin:16px 0 24px;font-size:34px">Reviens doucement dans la scène.</h2><div class="hint-list"><p>Où étais-tu assis, debout, en train de marcher ?</p><p>Qu’entendais-tu autour de toi ?</p><p>Quel petit détail te revient, même s’il semble sans importance ?</p></div><div class="btnrow">${btn('Ajouter ce qui me revient','edit','',`data-id="${mid}"`)}${btn('Chercher une autre piste','source','light',`data-id="${mid}"`)}</div>`);}
function prepareShare(mid=null,kind='share'){const step=session?.steps[session.index];shareContext={memoryId:mid,kind,period:step?.type==='explore'?sessionPeriod(step):'',year:step?.year,category:step?.category};editor=null;shareForm();}
function shareForm(){const ctx=shareContext,m=ctx.memoryId?getMemory(ctx.memoryId):null;showDialog(ctx.kind==='ask'?'Retrouver ce moment ensemble':'Préparer le partage',`<form id="share-form" style="margin-top:22px">${!m&&ctx.kind==='share'?`<div class="field"><label for="share-memory">Le souvenir à partager</label><select id="share-memory" name="memory">${memories().map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('')}</select></div>`:m?`<div class="source-card"><span class="small muted">Seulement ce souvenir</span><h3 style="margin:6px 0">${esc(m.title)}</h3><p style="font-size:16px">${esc(dateLabel(m.date))}</p></div>`:`<p class="small muted" style="margin-bottom:18px">À propos de ${esc(ctx.period||'cette période de ta vie')}</p>`}<div class="field"><label for="share-person">Avec qui ?</label><input id="share-person" name="people" required maxlength="200" value="${esc(m?.people?.[0]||'')}" placeholder="Un ou plusieurs prénoms, séparés par des virgules"></div><div class="field"><label for="share-message">${ctx.kind==='ask'?'Ta question':'Le message qui accompagne ce souvenir'}</label><textarea id="share-message" name="message" required maxlength="2000">${esc(ctx.kind==='ask'?m?`Tu te souviens de « ${m.title} » ? Quels détails te reviennent ?`:`Qu’est-ce qui te revient de ${ctx.period||'cette période'} ? J’aimerais retrouver un moment partagé.`:`Ce souvenir m’est revenu. J’avais envie de le partager avec toi.`)}</textarea></div><div class="field"><label for="share-permission">Ce que ces personnes pourraient faire</label><select id="share-permission" name="permission"><option value="view">Lire ce souvenir</option><option value="comment" ${ctx.kind==='share'?'selected':''}>Lire et laisser un commentaire</option><option value="contribute" ${ctx.kind==='ask'?'selected':''}>Proposer des détails à relire ensemble</option></select></div><label class="checkbox"><input name="propose" type="checkbox">Proposer aussi ce souvenir pour leur frise, avec leur accord.</label><div class="btnrow"><button class="btn" type="submit">Voir côté invité ${icon('arrow')}</button></div></form>`);}
function requestSnapshot(req){if(req.snapshot)return req.snapshot;const m=getMemory(req.memoryId);return m?{title:m.title,text:m.text,when:dateLabel(m.date)}:{title:'Un moment à retrouver',text:'',when:req.period||'Date encore ouverte'};}
function guestPreview(rid){const r=active().requests.find(x=>x.id===rid);if(!r)return;if(r.revoked){toast('Cet aperçu a été retiré.');return;}const m=requestSnapshot(r);showDialog('Aperçu invité',`<div class="guest-card"><div class="brand" style="font-size:21px">Memory<span class="x">X</span></div><p class="small" style="margin-top:14px">${db.scope==='demo'?'Alex':'Ton proche'} aimerait retrouver ce moment avec toi.</p><h2 style="font-size:32px;margin:14px 0 8px">${esc(m.title)}</h2><span class="small muted">${esc(m.when)}</span>${m.text?`<p style="margin:14px 0;color:var(--ink);white-space:pre-wrap">${esc(m.text)}</p>`:''}<blockquote>${esc(r.message)}</blockquote><span class="pill">${{view:'Lecture seule',comment:'Tu peux laisser un commentaire',contribute:'Tu peux proposer un détail'}[r.permission]}</span></div>${r.permission!=='view'?`<form id="contribution-form" data-id="${r.id}"><div class="field"><label for="contribution-person">Je réponds en tant que</label><select id="contribution-person" name="person">${r.people.map(p=>`<option>${esc(p)}</option>`).join('')}</select></div><div class="field"><label for="contribution-text">${r.permission==='comment'?'Mon commentaire':'Ce dont je me souviens'}</label><textarea id="contribution-text" name="text" required maxlength="3000" placeholder="Ah oui, je m’en souviens…"></textarea></div><div class="field"><label for="contribution-certainty">Ma certitude</label><select id="contribution-certainty" name="certainty"><option value="maybe">Je crois, mais j’ai un doute</option><option value="sure">Je m’en souviens clairement</option></select></div>${r.propose?`<label class="checkbox"><input type="checkbox" name="acceptTimeline">Tester l’accord pour ajouter ce souvenir à ma frise.</label>`:''}<button class="btn" type="submit">Tester ma réponse ${icon('arrow')}</button></form>`:`<p class="small muted">Ce partage permet seulement de lire. Les commentaires sont désactivés.</p>${r.propose?btn('Simuler mon accord pour ma frise','guest-consent','light',`data-id="${r.id}"`):''}`}<div class="dialog-footer">${btn('Revenir à mon espace','friends-return','light')}</div>`);}
function friendsView(){const data=active(),pending=data.contributions.filter(c=>c.state==='pending');return pagehead('','Ensemble.','',btn(icon('plus')+' Une demande','ask'))+`<div class="friends-layout"><section>${pending.map(c=>`<article class="request-item"><div class="row"><span class="avatar">${esc(c.person.slice(0,1))}</span><div><b class="small">${esc(c.person)}</b><p class="small">${c.certainty==='sure'?'S’en souvient':'Garde un doute'}</p></div></div><div class="contribution"><p>${esc(c.text)}</p></div><p class="small muted">${esc(getMemory(c.memoryId)?.title||'Un moment à retrouver')}</p><div class="review-buttons">${btn('Garder ce témoignage','accept-contribution','sm',`data-id="${c.id}"`)}${btn('Écarter','reject-contribution','light sm',`data-id="${c.id}"`)}</div></article>`).join('')}${data.requests.length?data.requests.slice().reverse().map(r=>`<article class="request-item"><div class="spread"><span class="pill">${r.revoked?'Retiré':'Brouillon'}</span><span class="small muted">${esc(r.people.join(', '))}</span></div><h3>${esc(requestSnapshot(r).title)}</h3><p style="margin-top:12px;font-size:13px;white-space:pre-wrap">${esc(r.message)}</p><div class="review-buttons">${!r.revoked?btn('Voir côté invité','guest','light sm',`data-id="${r.id}"`)+`<button class="textbtn" data-action="revoke" data-id="${r.id}">Retirer</button>`:''}</div></article>`).join(''):`<div class="empty">${icon('people')}<h2>Un souvenir en commun ?</h2><p>Choisis un proche et pose-lui ta question.</p>${btn('Préparer une question','ask','light')}</div>`}</section><aside>${memories().length?`<div class="panel"><h3>Partager un souvenir</h3><div class="btnrow">${btn('Choisir dans ma frise','share','light sm')}</div></div>`:''}</aside></div>`;}

function acceptContribution(cid){const c=active().contributions.find(x=>x.id===cid);if(!c||c.state!=='pending')return;let m=getMemory(c.memoryId);if(!m){const r=active().requests.find(x=>x.id===c.requestId);m={id:id(),title:'Un moment retrouvé avec '+c.person,text:'',date:r?.year?{type:'year',year:r.year}:{type:'unknown'},category:r?.category||'people',people:[c.person],place:'',status:'hypothesis',source:'Témoignage d’exemple de '+c.person,example:db.scope==='demo'};active().memories.push(m);c.memoryId=m.id;if(r)r.memoryId=m.id;}c.state='accepted';persist();render();detail(m.id);savedToast('Témoignage conservé avec son auteur. Il reste à vérifier.');}
function settingsView(){return pagehead('Ton espace','Mes données.','')+`<div class="settings-layout"><section class="panel"><h2>Mes rappels</h2><p>Aperçu des préférences.</p><form id="preferences-form"><label class="checkbox"><input name="reminders" type="checkbox" ${db.prefs.reminders?'checked':''}>Préparer un rappel pour mes pauses souvenirs</label><div class="twocol"><div class="field"><label for="cadence">Mon rythme</label><select id="cadence" name="cadence"><option value="weekly" ${db.prefs.cadence==='weekly'?'selected':''}>Une fois par semaine</option><option value="thrice" ${db.prefs.cadence==='thrice'?'selected':''}>Trois fois par semaine</option><option value="daily" ${db.prefs.cadence==='daily'?'selected':''}>Chaque jour</option></select></div><div class="field"><label for="reminder-time">Mon moment</label><input id="reminder-time" name="time" type="time" value="${esc(db.prefs.time)}" required></div></div><button class="btn" type="submit">Garder ces préférences</button></form></section><section class="panel"><h2>Mes souvenirs</h2><p>Les essais sont conservés dans ce navigateur, sans synchronisation entre appareils. L’export permet de les garder et de les réimporter.</p><div class="notice">${db.scope==='demo'?'Exemple d’Alex.':'Mon histoire.'} ${memories().length} souvenir(s).</div><div class="settings-actions">${btn(icon('download')+' Exporter cette histoire','export','light')}${btn(icon('upload')+' Importer un export MemoryX','import','light')}<input class="import-file" id="import-file" type="file" accept=".json,application/json"><span class="small muted">L’import ajoute les souvenirs à ton histoire personnelle. Il ne remplace rien.</span></div><div class="settings-actions">${db.scope==='demo'?btn('Passer à mon histoire','own','light'):btn('Explorer l’histoire d’exemple','demo','light')}${btn('Voir la corbeille ('+active().memories.filter(m=>m.deleted).length+')','trash','light')}${btn('Effacer les essais de cet espace','clear-data','light')}</div></section></div>${footer()}`;}
function about(){showDialog('À propos de cette démo',`<div class="about-content"><p>MemoryX aide à retrouver, enrichir et partager les souvenirs de sa vie.</p><h3>Ton espace</h3><p>Sans compte. Tes ajouts restent dans le navigateur de cet appareil. Tu peux les exporter dans <button class="inline-link" data-route="settings">Mes données</button>. Le lien de la démo ne contient pas tes souvenirs.</p><h3>Pour essayer</h3><p>L’histoire d’Alex et les images sont des exemples fictifs. Les souvenirs, la frise et les jeux fonctionnent. L’IA, les invitations et les réponses de proches sont des aperçus, sans connexion ni envoi de message. Aucun rappel n’est programmé.</p><p>Le site est public sur GitHub Pages. Il n’existe pas de sauvegarde serveur des souvenirs. Effacer les données du navigateur efface les essais locaux.</p><p class="small muted">MemoryX n’est pas un outil médical.</p></div><div class="btnrow">${btn('C’est compris','close')}</div>`);}
function chooseOwn(){db.scope='own';persist();session=null;editor=null;timelineScroll=null;zoom=8;filter={category:'all',query:''};go('timeline');if(!memories().length)editMemory();}
function exportData(){const payload={format:'memoryx-atelier',version:2,exportedAt:new Date().toISOString(),scope:db.scope,memories:clone(memories()).map(m=>({...m,clues:[...(m.clues||[]),...active().contributions.filter(c=>c.memoryId===m.id&&c.state==='accepted').map(c=>({id:c.id,text:c.text,source:'Témoignage d’exemple de '+c.person,status:'hypothesis'}))]})),requests:clone(active().requests),contributions:clone(active().contributions)};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='memoryx-'+(db.scope==='demo'?'exemple':'mon-histoire')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Export préparé. Il contient les souvenirs et les photos de cet espace.');}
// All actions are local to the current browser; no message or connector API is called.
document.addEventListener('click',e=>{const b=e.target.closest('button,a[data-route]');if(!b)return;
 if(b.dataset.route){e.preventDefault();if(b.dataset.route==='session'&&!session){startSession();return;}go(b.dataset.route);return;}
 if(b.dataset.category){rememberTimeline();filter.category=b.dataset.category;render();return;}
 if(b.dataset.sessionCategory){sessionSetup.category=b.dataset.sessionCategory;sessionSetup.drawn=false;render();return;}
 if(b.dataset.mode){sessionSetup.mode=b.dataset.mode;render();return;}
 if(b.dataset.dateType){captureEditor();const d=editor.date;editor.date={type:b.dataset.dateType,year:d.year||d.start||'',season:d.season||'summer',exact:d.exact||'',month:d.month||'',start:d.start||d.year||'',end:d.end||d.year||''};renderEditor();return;}
 if(b.dataset.editCategory){captureEditor();editor.category=b.dataset.editCategory;renderEditor();return;}
 const a=b.dataset.action,mid=b.dataset.id;
 if(a==='close')closeDialog();
 else if(a==='scope')showDialog('Ton histoire',`<div class="scope-options">${btn('Mon histoire','own','light')}${btn('Explorer l’exemple d’Alex','demo','light')}</div>`);
 else if(a==='share-app'){const url=new URL(location.href);url.hash='';navigator.clipboard?.writeText(url.href).then(()=>toast('Lien copié. Tu peux l’envoyer.')).catch(()=>showDialog('Partager MemoryX',`<div class="field"><label for="public-url">Le lien à envoyer</label><input id="public-url" value="${esc(url.href)}" readonly></div>`));if(!navigator.clipboard)showDialog('Partager MemoryX',`<input class="input" value="${esc(url.href)}" readonly aria-label="Lien de MemoryX">`);}
 else if(a==='toggle-search'){$('#timeline-search').classList.toggle('collapsed');if(!$('#timeline-search').classList.contains('collapsed'))$('#memory-search').focus();}
 else if(a==='undated')showDialog('Sans date pour l’instant',`<div class="undated-list">${memories().filter(m=>!interval(m.date)).map(card).join('')}</div>`);
 else if(a==='jump-year'){zoomAnchorId=null;const e=timelineMeta.entries.find(x=>new Date(x.i[0]).getUTCFullYear()===+b.dataset.year);if(e){$('#timeline-viewport').scrollTo({top:Math.max(0,e.y-25),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}}
 else if(a==='nearest'){const v=$('#timeline-viewport'),e=timelineMeta.entries.reduce((a,b)=>!a||Math.abs(b.y-v.scrollTop)<Math.abs(a.y-v.scrollTop)?b:a,null);if(e)v.scrollTo({top:e.y-30,behavior:'smooth'});}
 else if(a==='session-settings'){session=null;go('session');}
 else if(a==='about')about();
 else if(a==='add'){session&&(session.awaitingMemory=false);editMemory();}
 else if(a==='detail')detail(mid);
 else if(a==='edit')editMemory(mid);
 else if(a==='begin'||a==='pause'){session=null;sessionSetup.mode=a==='begin'?'explore':'mixed';go('session');}
 else if(a==='own')chooseOwn();
 else if(a==='start-own'||a==='empty-own'){db.scope='own';persist();session=null;editor=null;timelineScroll=null;filter={category:'all',query:''};go(a==='start-own'?'home':'timeline');if(a==='start-own')editMemory();}
 else if(a==='demo'){db.scope='demo';persist();session=null;editor=null;timelineScroll=null;filter={category:'all',query:''};go('home');}
 else if(a==='focus-memory'){const m=getMemory(mid),it=m&&interval(m.date);if(it){zoomAnchorId=mid;zoom=54;timelineScroll=null;centerTime=m.date.type==='exact'?it[0]:(it[0]+it[1])/2;closeDialog();route='timeline';location.hash=route;render();window.scrollTo(0,0);}else{toast('Ce souvenir n’a pas encore de date.');}}
 else if(a==='zoom-in')changeZoom(zoom+10);
 else if(a==='zoom-out')changeZoom(zoom-10);
 else if(a==='zoom-fit'){zoom=0;timelineScroll=0;render();}
 else if(a==='clear-filter'){filter={category:'all',query:''};render();}
 else if(a==='remove-photo'){captureEditor();editor.photo=null;renderEditor();}
 else if(a==='delete-memory'){showDialog('Retirer ce souvenir ?',`<p>Il sera placé dans la corbeille. Tu pourras le restaurer dans « Mon espace ».</p><div class="btnrow">${btn('Mettre à la corbeille','confirm-delete','danger',`data-id="${mid}"`)}${btn('Garder ce souvenir','detail','light',`data-id="${mid}"`)}</div>`);}
 else if(a==='confirm-delete'){const m=getMemory(mid);if(m){m.deleted=true;persist();editor=null;closeDialog();render();savedToast('Souvenir déplacé dans la corbeille.');}}
 else if(a==='trash'){const ms=active().memories.filter(m=>m.deleted);showDialog('Les souvenirs mis de côté',ms.length?ms.map(m=>`<div class="source-card"><h3>${esc(m.title)}</h3><p style="font-size:16px">${esc(dateLabel(m.date))}</p>${btn('Restaurer','restore','light sm',`data-id="${m.id}"`)}</div>`).join(''):'<p>La corbeille est vide.</p>');}
 else if(a==='restore'){const m=active().memories.find(m=>m.id===mid);if(m){delete m.deleted;persist();closeDialog();render();savedToast('Souvenir restauré.');}}
 else if(a==='roll'){const g=gaps(memories());const pool=g.filter(x=>x.count===g[0].count);sessionSetup.drawYear=pool[Math.floor(Math.random()*pool.length)].year;const cats=CATEGORIES.filter(c=>c.id!=='all');sessionSetup.drawCat=cats[Math.floor(Math.random()*cats.length)].id;sessionSetup.category=sessionSetup.drawCat;sessionSetup.scope='year';sessionSetup.period=String(sessionSetup.drawYear);sessionSetup.die1=1+Math.floor(Math.random()*6);sessionSetup.die2=1+Math.floor(Math.random()*6);sessionSetup.drawn=true;render();$('.dice-area')?.classList.add('rolling');toast(sessionSetup.drawYear+' · '+category(sessionSetup.drawCat).name);}
 else if(a==='start-session')startSession();
 else if(a==='reveal'){session.answer=$('#recall-answer')?.value||session.answer;session.revealed=true;render(true);}
 else if(a==='hint'){session.answer=$('#recall-answer')?.value||session.answer;session.hints=1;render();}
 else if(a==='next-step')nextStep();
 else if(a==='skip-step')nextStep(true);
 else if(a==='remember'){session.branch='remember';session.hints=1;render();}
 else if(a==='more-hint'){session.answer=$('#explore-note')?.value||session.answer;session.hints++;render();}
 else if(a==='choose-path'){session.answer=$('#explore-note')?.value||session.answer;session.branch=null;render();}
 else if(a==='save-explore'){session.answer=$('#explore-note')?.value||'';if(!session.answer.trim()){toast('Écris quelques mots sur ce qui te revient, ou passe ce moment.');$('#explore-note').focus();return;}session.awaitingMemory=true;editMemory(null,{...explorePreset(),title:session.answer.split(/[.!?\n]/)[0].slice(0,90),text:session.answer,status:'uncertain'});}
 else if(a==='explore-year'){session=null;sessionSetup={...sessionSetup,scope:'year',period:b.dataset.year,mode:'explore',category:filter.category};go('session');startSession();}
 else if(a==='exit-session'){showDialog('Une pause dans la pause ?',`<p>Les souvenirs et pistes déjà enregistrés restent dans ta frise. Tu peux reprendre cette session tant que cet onglet reste ouvert.</p><div class="btnrow">${btn('Revenir à l’accueil','pause-later')}${btn('Continuer ma pause','close','light')}</div>`);}
 else if(a==='pause-later')go('home');
 else if(a==='finish-session'){session=null;go('timeline');}
 else if(a==='restart-session'){session=null;render();}
 else if(a==='source')sourceView(mid||null);
 else if(a==='source-back')showSources();
 else if(a==='demo-sources')displayDemoSources();
 else if(a==='manual-source')manualSource();
 else if(a==='keep-demo-source')keepSource(demoSources().find(c=>c.id===b.dataset.clue),true);
 else if(a==='remove-clue'){const m=getMemory(mid);m.clues=m.clues.filter(c=>c.id!==b.dataset.clue);persist();detail(mid);}
 else if(a==='recall-help')helpMemory(mid);
 else if(a==='share'){if(!memories().length){toast('Ajoute un souvenir avant de préparer son partage.');return;}prepareShare(mid||null,'share');}
 else if(a==='ask')prepareShare(mid||null,'ask');
 else if(a==='guest')guestPreview(mid);
 else if(a==='friends-return')go('friends');
 else if(a==='guest-consent'){const r=active().requests.find(x=>x.id===mid);r.recipientConsent=true;persist();showDialog('Accord simulé',`<div class="notice">Le parcours d’acceptation a été testé. Aucune frise extérieure n’a été modifiée.</div><div class="btnrow">${btn('Revenir aux moments partagés','friends-return')}</div>`);}
 else if(a==='revoke'){const r=active().requests.find(x=>x.id===mid);r.revoked=true;persist();render();savedToast('Aperçu retiré.');}
 else if(a==='accept-contribution')acceptContribution(mid);
 else if(a==='reject-contribution'){const c=active().contributions.find(x=>x.id===mid);c.state='rejected';persist();render();savedToast('Contribution écartée, ton souvenir est inchangé.');}
 else if(a==='export')exportData();
 else if(a==='import')$('#import-file').click();
 else if(a==='clear-data')showDialog('Effacer cet espace sur cet appareil ?',`<p>Cela retirera les souvenirs, photos, brouillons et contributions de ${db.scope==='demo'?'l’histoire d’exemple':'ton histoire personnelle'} enregistrés dans ce navigateur. L’autre espace sera conservé.</p><p style="margin-top:16px">Tu peux télécharger une copie avant de continuer.</p><div class="btnrow">${btn('Exporter d’abord','export','light')}${btn('Effacer cet espace','confirm-clear','danger')}</div>`);
 else if(a==='confirm-clear'){db[db.scope]={memories:db.scope==='demo'?clone(SEED):[],requests:[],contributions:[]};persist();session=null;editor=null;timelineScroll=null;closeDialog();go('home');savedToast(db.scope==='demo'?'L’histoire d’exemple a retrouvé son état initial.':'Ton espace personnel est vide.');}
});
document.addEventListener('input',e=>{if(e.target.id==='zoom'){changeZoom(+e.target.value);}else if(e.target.id==='memory-search'){filter.query=e.target.value;const pos=e.target.selectionStart;rememberTimeline();render();const input=$('#memory-search');input.focus({preventScroll:true});input.setSelectionRange(pos,pos);}else if(e.target.id==='recall-answer'&&session)session.answer=e.target.value;else if(e.target.id==='explore-note'&&session)session.answer=e.target.value;});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='session-scope'){sessionSetup.scope=el.value;sessionSetup.period=el.value==='month'?'2019-07':el.value==='day'?'2019-07-01':'2019';sessionSetup.drawn=false;render();}else if(el.id==='session-period')sessionSetup.period=el.value;else if(el.id==='jump-year'&&el.value){zoomAnchorId=null;const v=$('#timeline-viewport');v.scrollTop=Math.max(0,45+(timelineMeta.end-yearStart(+el.value))/YEAR*timelineMeta.scale);paintTimeline();}
 else if(el.id==='memory-photo'){const file=el.files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>1500000){$('#photo-error').textContent='Choisis une image JPEG, PNG ou WebP de moins de 1,5 Mo.';el.value='';return;}captureEditor();const forId=editor.id,reader=new FileReader();reader.onload=()=>{if(editor?.id===forId){editor.photo=reader.result;renderEditor();}};reader.onerror=()=>{$('#photo-error').textContent='Cette photo n’a pas pu être lue. Essaie un autre fichier.';};reader.readAsDataURL(file);}
 else if(el.id==='import-file'){const file=el.files?.[0];if(!file)return;try{if(file.size>10000000)throw Error('Cet export dépasse 10 Mo. Essaie un fichier plus petit.');const imported=safeImport(JSON.parse(await file.text()));db.own.memories.push(...imported);db.scope='own';persist();session=null;timelineScroll=null;filter={category:'all',query:''};go('timeline');savedToast(imported.length+' souvenir(s) importé(s) dans ton histoire.');}catch(error){showDialog('L’import n’a pas abouti',`<div class="notice error" role="alert">${esc(error.message?.includes('JSON')?'Le fichier ne contient pas un export JSON valide.':error.message)}</div><p class="small muted" style="margin-top:16px">Tes souvenirs existants n’ont pas été modifiés.</p>`);}el.value='';}
});
document.addEventListener('submit',e=>{const f=e.target;if(f.id==='memory-form'){saveMemory(e);return;}e.preventDefault();const data=new FormData(f);
 if(f.id==='source-form'){const source=String(data.get('source')).trim(),txt=String(data.get('text')).trim();if(!source||!txt)return;keepSource({title:'Une piste à retrouver',memoryText:txt,source});}
 else if(f.id==='share-form'){const ctx=shareContext,selected=ctx.memoryId||data.get('memory'),m=selected?getMemory(selected):null;const people=String(data.get('people')).split(',').map(p=>p.trim()).filter(Boolean).slice(0,20),message=String(data.get('message')).trim();if(!people.length||!message)return;const r={id:id(),memoryId:selected||null,people,message,permission:data.get('permission'),propose:data.get('propose')==='on',kind:ctx.kind,period:ctx.period,year:ctx.year,category:ctx.category,createdAt:new Date().toISOString(),revoked:false,snapshot:m?{title:m.title,text:m.text,when:dateLabel(m.date)}:{title:'Un moment à retrouver',text:'',when:ctx.period||'Date encore ouverte'}};active().requests.push(r);persist();if(session&&session.steps[session.index]?.type==='explore')session.preparedRequest=r.id;guestPreview(r.id);savedToast('Brouillon conservé.');}
 else if(f.id==='contribution-form'){const r=active().requests.find(r=>r.id===f.dataset.id);if(!r||r.revoked||r.permission==='view'){toast('Ce parcours ne permet plus de contribuer.');return;}const txt=String(data.get('text')).trim();if(!txt)return;active().contributions.push({id:id(),requestId:r.id,memoryId:r.memoryId,person:String(data.get('person')),text:txt,certainty:data.get('certainty'),state:'pending'});if(data.get('acceptTimeline')==='on')r.recipientConsent=true;persist();go('friends');savedToast('Réponse ajoutée à relire.');}
 else if(f.id==='preferences-form'){db.prefs={reminders:data.get('reminders')==='on',cadence:data.get('cadence'),time:data.get('time')};persist();savedToast('Préférences enregistrées.');}
});
$('#dialog').addEventListener('cancel',()=>{if(editor)captureEditor();});
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1)||'timeline';if(r==='main'){$('#main').focus();return;}if(r!==route){if($('#dialog').open)closeDialog();route=r;render(true);window.scrollTo(0,0);}});
render();

document.addEventListener('keydown',e=>{const d=$('#dialog');if(!d.open||e.key!=='Tab')return;const items=[...d.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href],summary,[tabindex="0"]')].filter(el=>el.getClientRects().length);const first=items[0],last=items.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement.id==='dialog-title')){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}});
